USE cfb_load;

MERGE INTO cfb.dbo.rushing_plays AS target
USING cfb_load.dbo.rushing_plays AS source
ON target.game_id = source.game_id
	AND target.play_id = source.play_id
WHEN MATCHED THEN
	UPDATE SET
		drive_id = source.drive_id,
		season = source.season,
		week = source.week,
		season_type = source.season_type,
		offense_id = source.offense_id,
		offense = source.offense,
		offense_conference = source.offense_conference,
		defense_id = source.defense_id,
		defense = source.defense,
		defense_conference = source.defense_conference,
		period = source.period,
		clock_minutes = source.clock_minutes,
		clock_seconds = source.clock_seconds,
		down = source.down,
		distance = source.distance,
		play_text = source.play_text,
		start_yardline = source.start_yardline,
		start_yards_to_goal = source.start_yards_to_goal,
		rusher_id = source.rusher_id,
		rusher = source.rusher,
		rush_direction = source.rush_direction,
		rushing_yards = source.rushing_yards,
		rusher_yards = source.rusher_yards,
		is_rushing_touchdown = source.is_rushing_touchdown,
		is_sack = source.is_sack,
		is_kneel = source.is_kneel,
		is_team_rush = source.is_team_rush,
		attribution_status = source.attribution_status,
		direction_analysis_eligible = source.direction_analysis_eligible,
		parse_status = source.parse_status,
		ppa = source.ppa,
		success = source.success
WHEN NOT MATCHED THEN
	INSERT (
		game_id,
		play_id,
		drive_id,
		season,
		week,
		season_type,
		offense_id,
		offense,
		offense_conference,
		defense_id,
		defense,
		defense_conference,
		period,
		clock_minutes,
		clock_seconds,
		down,
		distance,
		play_text,
		start_yardline,
		start_yards_to_goal,
		rusher_id,
		rusher,
		rush_direction,
		rushing_yards,
		rusher_yards,
		is_rushing_touchdown,
		is_sack,
		is_kneel,
		is_team_rush,
		attribution_status,
		direction_analysis_eligible,
		parse_status,
		ppa,
		success
	)
	VALUES (
		source.game_id,
		source.play_id,
		source.drive_id,
		source.season,
		source.week,
		source.season_type,
		source.offense_id,
		source.offense,
		source.offense_conference,
		source.defense_id,
		source.defense,
		source.defense_conference,
		source.period,
		source.clock_minutes,
		source.clock_seconds,
		source.down,
		source.distance,
		source.play_text,
		source.start_yardline,
		source.start_yards_to_goal,
		source.rusher_id,
		source.rusher,
		source.rush_direction,
		source.rushing_yards,
		source.rusher_yards,
		source.is_rushing_touchdown,
		source.is_sack,
		source.is_kneel,
		source.is_team_rush,
		source.attribution_status,
		source.direction_analysis_eligible,
		source.parse_status,
		source.ppa,
		source.success
	);

TRUNCATE TABLE cfb_load.dbo.rushing_plays;
